async function searchAmazonCollect(keywords) {
  await tool.navigate({ tabId, url: `https://www.amazon.com/s?k=${encodeURIComponent(keywords)}` });
  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 8000 });
  return await browserjs(tabId, () => {
    return Array.from(document.querySelectorAll('[data-component-type="s-search-result"]')).map(el => {
      const title = el.querySelector('h2 a span')?.innerText?.trim() || el.querySelector('h2')?.innerText?.trim();
      const priceWhole = el.querySelector('.a-price-whole')?.innerText?.trim();
      const priceFraction = el.querySelector('.a-price-fraction')?.innerText?.trim();
      const price = priceWhole ? `$${priceWhole}${priceFraction ? '.' + priceFraction : ''}` : null;
      const asin = el.getAttribute('data-asin');
      return { asin, title, price };
    }).filter(x => x.asin && x.title);
  });
}

