    const bullets = Array.from(document.querySelectorAll("#feature-bullets li")).map(li => li.innerText.trim()).filter(Boolean);
    const techSpecs = {};
    document.querySelectorAll("#productDetails_techSpec_section_1 tr, #prodDetails tr, .prodDetTable tr").forEach(tr => {
      const th = tr.querySelector("th")?.innerText?.trim();
      const td = tr.querySelector("td")?.innerText?.trim();
      if (th && td) techSpecs[th] = td;
    });
    const overview = {};
    document.querySelectorAll(".product-facts-detail, #productOverview_feature_div tr").forEach(el => {
      const key = el.querySelector("td:first-child, .a-col-left")?.innerText?.trim();
      const val = el.querySelector("td:last-child, .a-col-right")?.innerText?.trim();
      if (key && val) overview[key] = val;
    });
    return { title, price, bullets, techSpecs, overview };
  });
}

