const tabId = 2017691780;

const duoReview = await browserjs(tabId, () => {
  const headings = Array.from(document.querySelectorAll('h2, h3, h4'));
  const h = headings.find(el => el.innerText.includes("Instant Pot Duo Mini"));
  if (h) {
    let text = h.innerText + "\n";
    let curr = h.nextElementSibling;
    for (let i = 0; i < 15 && curr; i++) {
      text += curr.innerText + "\n";
      curr = curr.nextElementSibling;
    }
    return text;
  }
  // If not found by heading, search text
  const text = document.body.innerText;
  const idx = text.indexOf("Instant Pot Duo Mini 3-Quart Pressure Cooker");
  return idx !== -1 ? text.slice(idx, idx + 2000) : "Not found";
});

console.log("Food & Wine Duo Mini specific review:", duoReview.slice(0, 1500));

