// Tab 2017691689: Product 1 - Instant Pot Rio Mini 4-Qt
await tool.navigate({ tabId: 2017691689, url: "https://www.amazon.com/dp/B0F9B923NC" });

// Tab 2017691778: Product 2 - COMFEE' 7-in-1 3-Qt
await tool.navigate({ tabId: 2017691778, url: "https://www.amazon.com/dp/B0FNC3PYK5" });

// Open a new tab for Product 3 - OLIXIS 10-In-1 3-Qt
const tabOlixis = (await tool.tabs_create({ url: "https://www.amazon.com/dp/B0H3BRX99X" })).details.tabId;

// Open a new tab for Manual - Instant Pot Duo Mini manual
const tabManual = (await tool.tabs_create({ url: "https://www.manualslib.com/manual/3280553/Instant-Pot-Duo-Mini.html?page=40#manual" })).details.tabId;

// Wait for pages to load
await tool.wait_for({ tabId: 2017691689, condition: "load_state", value: "load", timeout_ms: 8000 });
await tool.wait_for({ tabId: 2017691778, condition: "load_state", value: "load", timeout_ms: 8000 });
await tool.wait_for({ tabId: tabOlixis, condition: "load_state", value: "load", timeout_ms: 8000 });
await tool.wait_for({ tabId: tabManual, condition: "load_state", value: "load", timeout_ms: 8000 });

// Check all tabs
const ctx = await tool.tabs_context({});
console.log("Configured tabs:", JSON.stringify(ctx.pages, null, 2));

